"""Dataset inspection: visualize and quality-check recorded clips.

Generates an HTML report with:
  - Class distribution (counts, durations)
  - Per-clip thumbnails: log-mel spectrogram + waveform + audio playback

The report is a single self-contained HTML file (with inline base64 PNGs for
spectrograms and a copy of audio files served from a relative path).

Interactive mode (``--serve``) lets reviewers tick dataset/augmented clips for
soft exclusion from the next compose/train run. The "Delete selected" button
still permanently removes WAVs and sidecars from disk.
"""

from __future__ import annotations

import base64
import csv
import html
import io
import json
import logging
import threading
import time
import uuid
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import soundfile as sf
from rich.progress import Progress, SpinnerColumn, TextColumn, BarColumn, TimeRemainingColumn, MofNCompleteColumn

from sed.audio.features import (
    EFFICIENTAT_DISPLAY_RANGE,
    display_range_for_spec,
    pcen_params_from_features,
    preview_display_range,
    robust_display_range,
    waveform_to_feature,
    waveform_to_logmel,
)
from sed.config import Config, ProjectLayout
from sed.util import PhasedProgress

log = logging.getLogger(__name__)


def _load_exclusions_for_render(layout: ProjectLayout) -> set[str]:
    from sed.data.compose import load_excluded_clip_paths
    return load_excluded_clip_paths(layout)


# ---------------------------------------------------------------------------
# Plotting helpers — return base64 PNG strings
# ---------------------------------------------------------------------------


# Preview spectrograms must show what the model consumes. The active project's
# feature contract is registered here at render/serve time; thumbnail helpers
# read it instead of the historical waveform_to_logmel defaults (which were the
# legacy frontend at the file's native sample rate — NOT the model view).
_PREVIEW_FEATURES: dict = {}

# Fixed display range so brightness is comparable across clips instead of
# per-image autoscale. Quiet clips genuinely render darker than loud ones:
# that is the model's view (absolute level is signal), but nothing above the
# digital-silence floor is clipped. Shared with the augmentation mix maps.
_EFFICIENTAT_PREVIEW_RANGE = EFFICIENTAT_DISPLAY_RANGE
_THUMBNAIL_LAYOUT_VERSION = "time-x-square-min-v2"
_PREVIEW_CACHE = None


def set_preview_features(cfg: Config | None, layout: "ProjectLayout | None" = None) -> None:
    global _PREVIEW_FEATURES
    if cfg is None:
        _PREVIEW_FEATURES = {}
        return
    # Dataset previews render from a preview-only feature (Library tab) when one
    # is assigned; otherwise from the project's current config feature. This is
    # independent of the model/training [features] config.
    f, sample_rate = cfg.features, int(cfg.model.sample_rate)
    if layout is not None:
        try:
            from sed.data.presets import preview_feature_parts
            f, sample_rate = preview_feature_parts(cfg, layout)
        except Exception:  # noqa: BLE001 — preview override is best-effort
            log.debug("preview feature override unavailable", exc_info=True)
    _PREVIEW_FEATURES = {
        "sample_rate": int(sample_rate),
        "frontend": str(f.frontend),
        "feature_type": str(f.feature_type),
        "n_fft": int(f.n_fft),
        "win_length": int(f.win_length),
        "hop_length": int(f.hop_length),
        "n_mels": int(f.n_mels),
        "fmin": int(f.fmin),
        "fmax": int(f.fmax),
        "log_power": bool(f.log_power),
        "stft_engine": str(getattr(f, "stft_engine", "librosa")),
        "db_norm": bool(getattr(f, "db_norm", False)),
        "db_min": float(getattr(f, "db_min", -20.0)),
        "db_max": float(getattr(f, "db_max", 60.0)),
        "pcen": bool(f.pcen),
        "pcen_params": pcen_params_from_features(f),
        # Display range is part of the rendered art — changing it (or PCEN /
        # feature type) must also invalidate cached thumbnails.
        "display_range": list(preview_display_range(
            f.feature_type, f.log_power, f.pcen,
            db_norm=bool(getattr(f, "db_norm", False)),
        )),
        "thumbnail_layout": _THUMBNAIL_LAYOUT_VERSION,
    }
    _ensure_thumbnail_cache_matches_features()


def _ensure_thumbnail_cache_matches_features() -> None:
    """Register the current preview contract without deleting other variants."""
    if not _PREVIEW_FEATURES:
        return
    try:
        from sed.config import LIBRARY_DIR
        from sed.data.preview_cache import CACHE_DIRNAME, PreviewCache

        global _PREVIEW_CACHE
        if _PREVIEW_CACHE is None or _PREVIEW_CACHE.root != (LIBRARY_DIR / CACHE_DIRNAME):
            _PREVIEW_CACHE = PreviewCache()
        _PREVIEW_CACHE.register_variant(_preview_cache_features())
    except Exception as exc:  # noqa: BLE001
        log.warning("preview cache registration failed: %s", exc)


def _preview_cache_features() -> dict:
    """Canonical cache signature for the current inspect feature contract."""
    from sed.data.preview_cache import CACHE_LAYOUT_VERSION

    return {
        key: _PREVIEW_FEATURES[key]
        for key in (
            "sample_rate", "frontend", "feature_type", "n_fft", "win_length",
            "hop_length", "n_mels", "fmin", "fmax", "log_power",
            "stft_engine", "db_norm", "db_min", "db_max", "pcen", "pcen_params",
        )
    } | {"layout": CACHE_LAYOUT_VERSION, "palette_colors": 128}


def _feature_kwargs(p: dict) -> dict:
    """STFT/mel kwargs for waveform_to_feature, by feature type (PCEN-aware)."""
    feature_type = str(p.get("feature_type") or "mel")
    pcen = bool(p.get("pcen", False))
    common = {
        "n_fft": int(p["n_fft"]),
        "win_length": int(p["win_length"]),
        "hop_length": int(p["hop_length"]),
        "fmin": int(p["fmin"]),
        "fmax": int(p["fmax"]),
        "pcen": pcen,
        "pcen_params": p.get("pcen_params"),
    }
    if feature_type == "linear":
        return {
            **common,
            "log_power": bool(p.get("log_power", True)),
            "stft_engine": str(p.get("stft_engine", "librosa")),
            "db_norm": bool(p.get("db_norm", False)),
            "db_min": float(p.get("db_min", -20.0)),
            "db_max": float(p.get("db_max", 60.0)),
        }
    return {**common, "frontend": p["frontend"], "n_mels": int(p["n_mels"])}


def _preview_feature(wave: np.ndarray, sr: int) -> tuple[np.ndarray, float | None, float | None]:
    """Model-view feature for previews: resampled to the model rate and run
    through the configured frontend (mel or linear, ± PCEN). Returns (spec, vmin, vmax)."""
    p = _PREVIEW_FEATURES
    if not p:
        return waveform_to_logmel(wave, sample_rate=sr)[0], None, None
    target_sr = int(p["sample_rate"])
    if int(sr) != target_sr:
        from sed.audio.resample import resample_audio
        wave = resample_audio(wave, orig_sr=int(sr), target_sr=target_sr)
    feature_type = str(p.get("feature_type") or "mel")
    spec = waveform_to_feature(
        wave,
        sample_rate=target_sr,
        feature_type=feature_type,
        **_feature_kwargs(p),
    )
    if str(p.get("frontend") or "efficientat") == "ced":
        vmin, vmax = robust_display_range(spec)
    else:
        vmin, vmax = display_range_for_spec(
            spec, feature_type, bool(p.get("log_power", True)), bool(p.get("pcen", False)),
            db_norm=bool(p.get("db_norm", False)),
        )
    return spec, vmin, vmax


# Back-compat alias (mel-era name); now dispatches on the configured feature type.
_preview_logmel = _preview_feature


def _spectrogram_preview_pixels(spec: np.ndarray) -> np.ndarray:
    """Return display pixels with time on X and frequency on Y.

    EfficientAT windows are often slightly shorter in time frames than mel
    bands (e.g. 100x128 for a one-second clip). Widen only the time axis to a
    square minimum so short previews do not look rotated into a tall strip.
    """
    arr = np.asarray(spec)
    if arr.ndim != 2:
        return arr
    mel_bins, time_frames = arr.shape
    if mel_bins <= 0 or time_frames <= 0 or time_frames >= mel_bins:
        return arr
    col_idx = np.rint(np.linspace(0, time_frames - 1, mel_bins)).astype(np.intp)
    return arr[:, col_idx]


def _spectrogram_thumb(wave: np.ndarray, sr: int, height: int = 96) -> str:
    spec, vmin, vmax = _preview_logmel(wave, sr)   # (n_mels, T)
    buf = io.BytesIO()
    colormap = str((_PREVIEW_FEATURES or {}).get("colormap") or "none").lower()
    if colormap != "none":
        # Colormap image feature: render the exact model-input RGB image.
        from sed.audio.features import render_spectrogram_image
        img = render_spectrogram_image(
            spec, colormap, int((_PREVIEW_FEATURES or {}).get("image_size", 96))
        )
        plt.imsave(buf, np.transpose(img, (1, 2, 0)), format="png")
        return base64.b64encode(buf.getvalue()).decode("ascii")
    plt.imsave(
        buf,
        _spectrogram_preview_pixels(spec),
        format="png",
        origin="lower",
        cmap="magma",
        vmin=vmin,
        vmax=vmax,
    )
    return base64.b64encode(buf.getvalue()).decode("ascii")


